SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='5397c57b-dd41-5a97-934c-fcadeba53c3e'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('d8bccb3e-6a64-5a89-92df-4b6648eb2e66','9fce1e89-84aa-53da-a8bc-3a1bf992968f')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='5397c57b-dd41-5a97-934c-fcadeba53c3e'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='5397c57b-dd41-5a97-934c-fcadeba53c3e'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('d8bccb3e-6a64-5a89-92df-4b6648eb2e66','9fce1e89-84aa-53da-a8bc-3a1bf992968f')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='5397c57b-dd41-5a97-934c-fcadeba53c3e'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='d8bccb3e-6a64-5a89-92df-4b6648eb2e66' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-02-missing-evidence' AND q.fingerprint='c87512be0ec858b32a3c3b9f9d277d5d28b0925eaa251cf3cf6dcc7682eb5ade'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-02-missing-evidence","status":"ok","value":{"customerProfileId":"5397c57b-dd41-5a97-934c-fcadeba53c3e","userId":"84a7a701-d7e6-5d62-8a1d-842087d53942","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"d8bccb3e-6a64-5a89-92df-4b6648eb2e66","semanticKey":"customer-controls-customer-02-missing-evidence","fingerprint":"c87512be0ec858b32a3c3b9f9d277d5d28b0925eaa251cf3cf6dcc7682eb5ade","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='f71239fd-9e60-5680-b951-d67dd3df14d9' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='0ecb1ada-2dfb-5e26-b1da-f8aaf24d0dba' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"5397c57b-dd41-5a97-934c-fcadeba53c3e"},"prior":null,"committed":{"id":"5397c57b-dd41-5a97-934c-fcadeba53c3e","userId":"84a7a701-d7e6-5d62-8a1d-842087d53942","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='5397c57b-dd41-5a97-934c-fcadeba53c3e' AND c.user_id='84a7a701-d7e6-5d62-8a1d-842087d53942' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-02-missing-evidence' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='0bcfeb5b-fd5d-55f3-a807-970aa07c36d9' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"5397c57b-dd41-5a97-934c-fcadeba53c3e","userId":"84a7a701-d7e6-5d62-8a1d-842087d53942","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='b246cbb9-387b-50f4-9a11-648191a0805c' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"84a7a701-d7e6-5d62-8a1d-842087d53942","track":"customer","customerProfileId":"5397c57b-dd41-5a97-934c-fcadeba53c3e","sourceCreationRevision":"0","sourceCreationReceipt":"d8bccb3e-6a64-5a89-92df-4b6648eb2e66","semanticKey":"customer_buyer_profile/5397c57b-dd41-5a97-934c-fcadeba53c3e/default-free-enrollment/v1"}'::jsonb)))=2));
